// Extract conversation data from webhook
const inputData = $input.first().json;
const body = inputData.body || inputData;

const sessionId = body.sessionId || `session-${Date.now()}`;
const userMessage = body.message;
const userId = body.userId || 'anonymous';
const channel = body.channel || 'web';

if (!userMessage) {
  throw new Error('Message is required');
}

return {
  json: {
    sessionId: sessionId,
    userId: userId,
    userMessage: userMessage,
    channel: channel,
    timestamp: new Date().toISOString(),
    chatInput: userMessage
  }
};

// Check calendar availability for the requested date
const preferredDate = $input.item.json.preferredDate;

if (!preferredDate) {
  return { error: 'Preferred date is required' };
}

// Validate date format
const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
if (!dateRegex.test(preferredDate)) {
  return { error: 'Invalid date format. Please use YYYY-MM-DD' };
}

// Check day of week
const date = new Date(preferredDate);
const dayOfWeek = date.getDay();

if (dayOfWeek === 0) {
  return {
    available: false,
    reason: 'La clínica está cerrada los domingos',
    availableSlots: [],
    nextAvailableDate: null
  };
}

// Define working hours
let startHour = 8;
let endHour = 18;
if (dayOfWeek === 6) {
  startHour = 9;
  endHour = 14;
}

// Generate available time slots (30-minute intervals)
const allSlots = [];
for (let hour = startHour; hour < endHour; hour++) {
  for (let minute of [0, 30]) {
    const timeSlot = `${String(hour).padStart(2, '0')}:${String(minute).padStart(2, '0')}`;
    allSlots.push(timeSlot);
  }
}

// For demo purposes, simulate some occupied slots
const occupiedSlots = ['09:00', '09:30', '14:00', '15:30'];
const availableSlots = allSlots.filter(slot => !occupiedSlots.includes(slot));

return {
  available: availableSlots.length > 0,
  availableSlots: availableSlots.slice(0, 10),
  requestedDate: preferredDate,
  totalSlotsAvailable: availableSlots.length,
  clinicHours: `${startHour}:00 - ${endHour}:00`
};

// Create appointment with Google Calendar
const input = $input.item.json;

// Validate required fields
const requiredFields = ['patientName', 'patientAge', 'parentName', 'parentEmail', 'parentPhone', 'preferredDate', 'preferredTime', 'reasonForVisit'];
for (const field of requiredFields) {
  if (!input[field]) {
    return { error: `Missing required field: ${field}` };
  }
}

// Create appointment ID
const appointmentId = `APT-${Date.now()}`;

// Calculate end time (30 minutes after start)
const startDateTime = new Date(`${input.preferredDate}T${input.preferredTime}:00`);
const endDateTime = new Date(startDateTime.getTime() + 30 * 60000);

// Format the appointment details
const appointmentDetails = {
  appointmentId: appointmentId,
  patient: {
    name: input.patientName,
    age: input.patientAge
  },
  parent: {
    name: input.parentName,
    email: input.parentEmail,
    phone: input.parentPhone
  },
  dateTime: startDateTime.toISOString(),
  endDateTime: endDateTime.toISOString(),
  reason: input.reasonForVisit,
  status: 'scheduled',
  location: 'Kids Growing - Clínica Pediátrica',
  address: 'Av. Principal #123, Ciudad'
};

// Return confirmation
return {
  success: true,
  message: `Cita agendada exitosamente para ${input.patientName}`,
  appointmentId: appointmentId,
  details: appointmentDetails,
  confirmationMessage: `✅ **Cita Confirmada**\n\n**Paciente:** ${input.patientName} (${input.patientAge})\n**Fecha:** ${input.preferredDate}\n**Hora:** ${input.preferredTime}\n**Motivo:** ${input.reasonForVisit}\n\n**Datos de contacto:**\n${input.parentName}\n${input.parentEmail}\n${input.parentPhone}\n\nRecibirás un correo de confirmación en ${input.parentEmail}.\n\n📍 **Ubicación:** Kids Growing - Clínica Pediátrica, Av. Principal #123, Ciudad`
};

// Look up pricing information
const searchQuery = ($input.item.json.searchQuery || '').toLowerCase();

// Simulated pricing database (in production, this would query Google Sheets or database)
const pricingData = [
  {
    category: 'Consultas',
    name: 'Consulta Pediátrica General',
    description: 'Consulta médica general con pediatra certificado',
    price: '$500 MXN',
    duration: '30 minutos'
  },
  {
    category: 'Consultas',
    name: 'Control de Niño Sano',
    description: 'Revisión preventiva, medición y evaluación del desarrollo',
    price: '$450 MXN',
    duration: '30 minutos'
  },
  {
    category: 'Consultas',
    name: 'Consulta de Urgencia',
    description: 'Atención prioritaria para casos urgentes',
    price: '$800 MXN',
    duration: '30 minutos'
  },
  {
    category: 'Vacunas',
    name: 'Vacuna Influenza',
    description: 'Vacuna contra la gripe estacional',
    price: '$350 MXN',
    notes: 'Aplicación incluida'
  },
  {
    category: 'Vacunas',
    name: 'Vacuna Hepatitis B',
    description: 'Vacuna contra Hepatitis B',
    price: '$400 MXN',
    notes: 'Esquema de 3 dosis'
  },
  {
    category: 'Procedimientos',
    name: 'Nebulización',
    description: 'Tratamiento respiratorio con nebulizador',
    price: '$200 MXN',
    duration: '15-20 minutos'
  },
  {
    category: 'Procedimientos',
    name: 'Curación',
    description: 'Curación de heridas menores',
    price: '$150 MXN',
    duration: '15 minutos'
  }
];

// Search for matching services
const matchedServices = pricingData.filter(service => {
  const searchLower = searchQuery.toLowerCase();
  return service.name.toLowerCase().includes(searchLower) ||
         service.category.toLowerCase().includes(searchLower) ||
         service.description.toLowerCase().includes(searchLower);
});

if (matchedServices.length === 0) {
  return {
    found: false,
    message: 'No encontré información sobre ese servicio. Servicios disponibles: Consulta Pediátrica General, Control de Niño Sano, Consulta de Urgencia, Vacunas, Nebulización, Curación.',
    availableCategories: ['Consultas', 'Vacunas', 'Procedimientos']
  };
}

// Format results
let formattedMessage = '';
if (matchedServices.length === 1) {
  const s = matchedServices[0];
  formattedMessage = `📋 **${s.name}**\n\n${s.description}\n\n💰 **Precio:** ${s.price}`;
  if (s.duration) formattedMessage += `\n⏱️ **Duración:** ${s.duration}`;
  if (s.notes) formattedMessage += `\n\n📝 *Nota:* ${s.notes}`;
} else {
  formattedMessage = `Encontré ${matchedServices.length} servicios:\n\n`;
  matchedServices.forEach((s, i) => {
    formattedMessage += `${i+1}. **${s.name}** - ${s.price}\n   ${s.description}\n\n`;
  });
}

return {
  found: true,
  message: formattedMessage,
  services: matchedServices,
  totalResults: matchedServices.length
};

// Cancel appointment
const appointmentId = $input.item.json.appointmentId;
const reason = $input.item.json.reason || 'No especificado';

if (!appointmentId) {
  return { error: 'Appointment ID is required' };
}

// In production, this would update Google Calendar and database
// For now, return a confirmation
return {
  success: true,
  message: `La cita ${appointmentId} ha sido cancelada exitosamente`,
  appointmentId: appointmentId,
  cancellationReason: reason,
  refundInfo: 'Si realizaste un pago adelantado, el reembolso se procesará en 5-7 días hábiles',
  confirmationMessage: `✅ **Cita Cancelada**\n\n**ID de Cita:** ${appointmentId}\n**Motivo:** ${reason}\n\nLa cancelación ha sido procesada. Recibirás un correo de confirmación.\n\nSi deseas reagendar, con gusto puedo ayudarte a encontrar un nuevo horario.`
};

